urlset:
{%- for locale, i18n_files in i18n_alternates.items() %}
{%- for file in i18n_files %}
{%- set page = file.page %}
{%- if page and not page.is_link and not page.meta.duplicate and "noindex" not in page.meta.robots | default("") %}

        {{ page.canonical_url | e }}
        {{ page.update_date }}
    {%- for code, url in page.meta.hreflang.items() %}

    {%- endfor %}

{%- endif %}
{%- endfor %}
{%- endfor %}
